<script setup lang="ts">
import { computed,onMounted,ref,watch } from 'vue'
import { ApiError,get,post,session } from '../api'
import RiskTag from '../components/RiskTag.vue'
const data=ref<any>(), clients=ref<any[]>([]), year=ref(''), client=ref(''), service=ref(''), loading=ref(false), saving=ref(false), drawer=ref(false), recordType=ref<'contract'|'invoice'|'payment'>('contract'), error=ref(''), record=ref<any>({projectId:'',contractId:'',amount:null,signedDate:'',expectedPaymentDate:'',invoiceDate:'',paymentDate:'',contractNo:'',invoiceNo:'',note:''})
const allContracts=computed(()=>data.value?.projects.flatMap((p:any)=>p.contracts.map((c:any)=>({...c,projectName:p.name})))||[])
const money=(n:number)=>`¥${Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:2})}`
async function load(){loading.value=true;error.value='';try{const q=new URLSearchParams();if(year.value)q.set('businessYear',year.value);if(client.value)q.set('clientId',client.value);if(service.value)q.set('serviceType',service.value);data.value=await get(`/finance/overview?${q}`)}catch(e){error.value=e instanceof ApiError?e.message:'经营数据加载失败'}finally{loading.value=false}}
async function save(){saving.value=true;error.value='';try{await post(`/finance/${recordType.value}`,record.value);drawer.value=false;record.value={projectId:'',contractId:'',amount:null,signedDate:'',expectedPaymentDate:'',invoiceDate:'',paymentDate:'',contractNo:'',invoiceNo:'',note:''};await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}
onMounted(async()=>{try{clients.value=await get('/settings/clients')}catch(e){error.value=e instanceof Error?e.message:'基础数据加载失败'}await load()});watch([year,client,service],load)
</script>
<template><div class="heading"><div><h1 class="title">经营</h1><p class="subtitle">项目经营口径，不替代财务会计。</p></div><button v-if="!session.isDemo" class="button primary" @click="drawer=true">＋ 记录经营</button></div><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="loading&&!data" class="empty">正在加载经营数据…</div><template v-else-if="data"><div class="finance-head"><section class="kpis"><div v-for="row in [['合同额',data.contractAmount],['已开票',data.invoiceAmount],['已回款',data.paymentAmount],['应收',data.receivableAmount]]" :key="row[0]" class="kpi"><div class="kpi-num">{{money(Number(row[1]))}}</div><div class="kpi-label">{{row[0]}}</div></div></section><aside class="overdue"><label>逾期应收</label><strong style="font-size:32px;display:block;margin-top:12px">{{money(data.overdueAmount)}}</strong><p>按合同计划回款日期实时计算</p></aside></div><div class="control-bar"><span class="eyebrow">经营范围</span><select v-model="year" class="select"><option value="">全部年份</option><option value="2026">2026</option><option value="2025">2025</option></select><select v-model="service" class="select"><option value="">全部服务</option><option value="BIDDING">招标代理</option><option value="COST">造价/预结算</option><option value="SUPERVISION">监理</option><option value="OTHER">其他</option></select><select v-model="client" class="select"><option value="">全部客户</option><option v-for="c in clients" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div v-if="!data.projects.length" class="empty"><h3>当前范围没有项目</h3><p>调整筛选条件，或先创建一个项目。</p></div><div v-else class="table-wrap"><table class="data-table"><thead><tr><th>项目</th><th>合同额</th><th>已开票</th><th>已回款</th><th>应收</th></tr></thead><tbody><tr v-for="project in data.projects" :key="project.id" class="clickable" @click="$router.push(`/projects/${project.id}`)"><td data-label="项目" style="font-weight:650">{{project.name}}</td><td data-label="合同额">{{money(project.finance.contractAmount)}}</td><td data-label="已开票">{{money(project.finance.invoiceAmount)}}</td><td data-label="已回款">{{money(project.finance.paymentAmount)}}</td><td data-label="应收">{{money(project.finance.receivableAmount)}} <RiskTag v-if="project.risks?.some((x:any)=>x.reason.includes('应收'))" level="danger" text="逾期"/></td></tr></tbody></table></div></template><el-drawer v-if="!session.isDemo" v-model="drawer" title="记录经营" size="min(540px,100%)"><div class="service-chips"><button v-for="x in [['contract','合同'],['invoice','发票'],['payment','回款']]" :key="x[0]" class="chip" :class="{active:recordType===x[0]}" @click="recordType=x[0]">{{x[1]}}</button></div><form class="form-section" @submit.prevent="save"><div v-if="recordType==='contract'" class="field-group"><label>项目</label><select v-model="record.projectId" class="select" required><option value="">选择项目</option><option v-for="p in data?.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><label>合同编号</label><input v-model.trim="record.contractNo" class="input" required/><label>签订日期</label><input v-model="record.signedDate" type="date" class="input"/><label>计划回款日期</label><input v-model="record.expectedPaymentDate" type="date" class="input"/></div><div v-else class="field-group"><label>合同</label><select v-model="record.contractId" class="select" required><option value="">选择合同</option><option v-for="c in allContracts" :key="c.id" :value="c.id">{{c.projectName}} · {{c.contractNo}}</option></select><label>{{recordType==='invoice'?'发票编号':'回款日期'}}</label><input v-if="recordType==='invoice'" v-model.trim="record.invoiceNo" class="input" required/><input v-else v-model="record.paymentDate" type="date" class="input" required/><label v-if="recordType==='invoice'">开票日期</label><input v-if="recordType==='invoice'" v-model="record.invoiceDate" type="date" class="input" required/></div><div class="field-group" style="margin-top:16px"><label>金额</label><input v-model.number="record.amount" type="number" min="0.01" step="0.01" class="input" required/><label>备注</label><textarea v-model="record.note" class="textarea" rows="3"/></div><div class="actions"><button class="button primary" :disabled="saving">{{saving?'保存中…':'保存记录'}}</button></div></form></el-drawer></template>
